{
  "id": "V022",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "고객 의견의 주제별 경향을 정리해 회의에 활용하려는 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "의견 검토, 경향 분석 및 근거 의견을 담은 요약 자료 작성이 보존됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "고객 의견의 반복되는 요구와 불편 주제가 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "이번 주 또는 매주 접수된 고객 의견이 입력으로 제시됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "경향과 근거 의견을 포함한 회의용 요약 자료가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "개별 고객 답장과 제품 개선 효과 예측을 제외한다는 제약이 BUSINESS 뷰에 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능이 추가되지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "서비스 기획팀의 역할이 BUSINESS 및 OPERATIONS 뷰에 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "개별 고객에게 답장하거나 제품 개선 효과를 예측하는 작업은 제외됨. 그 밖의 권한이나 필수 수행 주체에 대한 변경은 없음."
}
